package ai.finsight.health;

import ai.finsight.budget.*;import ai.finsight.goal.*;import ai.finsight.transaction.*;import ai.finsight.user.UserRepository;
import org.springframework.jdbc.core.namedparam.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.time.*;import java.util.*;

@Service public class HealthScoreService{
 public record Component(String key,String label,int weight,BigDecimal points,BigDecimal observedValue,boolean available,String explanation){}
 public record Assessment(BigDecimal score,int confidenceWeight,String confidence,List<Component> components,List<String> limitations,String disclaimer){}
 private final UserRepository users;private final TransactionRepository tx;private final NamedParameterJdbcTemplate jdbc;private final BudgetService budgets;private final FinancialGoalRepository goals;
 public HealthScoreService(UserRepository u,TransactionRepository t,NamedParameterJdbcTemplate j,BudgetService b,FinancialGoalRepository g){users=u;tx=t;jdbc=j;budgets=b;goals=g;}
 @Transactional(readOnly=true) public Assessment assess(String email){UUID owner=users.findByEmailIgnoreCase(email).orElseThrow().getId();LocalDate today=LocalDate.now(),monthStart=today.withDayOfMonth(1),nextMonth=monthStart.plusMonths(1);BigDecimal income=tx.sumForOwnerAndPeriod(owner,monthStart,nextMonth,FinancialTransaction.Direction.INCOME),expenses=tx.sumForOwnerAndPeriod(owner,monthStart,nextMonth,FinancialTransaction.Direction.EXPENSE);BigDecimal savingRate=income.signum()==0?null:income.subtract(expenses).multiply(BigDecimal.valueOf(100)).divide(income,2,RoundingMode.HALF_UP);List<Component> out=new ArrayList<>();int available=0;BigDecimal earned=BigDecimal.ZERO;
  BigDecimal savingsPoints=savingRate==null?BigDecimal.ZERO:ratio(savingRate.max(BigDecimal.ZERO),BigDecimal.valueOf(20)).multiply(BigDecimal.valueOf(30));out.add(new Component("savingsRate","Savings rate",30,points(savingsPoints),savingRate,savingRate!=null,"30 points at a savings rate of 20% or more; below that, points scale linearly from zero. Uses current calendar month transactions."));if(savingRate!=null){available+=30;earned=earned.add(savingsPoints);}
  BigDecimal avgExpenses=historyAverage(owner,FinancialTransaction.Direction.EXPENSE);BigDecimal cash=jdbc.queryForObject("SELECT COALESCE(SUM(current_value),0) FROM financial_asset WHERE user_id=:user AND category IN ('Cash','Bank Account')",new MapSqlParameterSource("user",owner),BigDecimal.class);boolean emergencyAvailable=avgExpenses.signum()>0;BigDecimal months=emergencyAvailable?cash.divide(avgExpenses,4,RoundingMode.HALF_UP):null;BigDecimal emergencyPoints=emergencyAvailable?ratio(months,BigDecimal.valueOf(6)).multiply(BigDecimal.valueOf(25)):BigDecimal.ZERO;out.add(new Component("emergencyFund","Emergency fund coverage",25,points(emergencyPoints),months,emergencyAvailable,"Cash and bank assets divided by average expenses over the last three complete months; 25 points at six months of coverage."));if(emergencyAvailable){available+=25;earned=earned.add(emergencyPoints);}
  BigDecimal avgIncome=historyAverage(owner,FinancialTransaction.Direction.INCOME);BigDecimal emi=jdbc.queryForObject("SELECT COALESCE(SUM(monthly_emi),0) FROM financial_liability WHERE user_id=:user",new MapSqlParameterSource("user",owner),BigDecimal.class);boolean debtAvailable=avgIncome.signum()>0;BigDecimal dti=debtAvailable?emi.multiply(BigDecimal.valueOf(100)).divide(avgIncome,2,RoundingMode.HALF_UP):null;BigDecimal debtPoints=debtAvailable?BigDecimal.valueOf(40).subtract(dti).max(BigDecimal.ZERO).divide(BigDecimal.valueOf(20),8,RoundingMode.HALF_UP).min(BigDecimal.ONE).multiply(BigDecimal.valueOf(20)):BigDecimal.ZERO;out.add(new Component("debtToIncome","Debt-to-income commitment",20,points(debtPoints),dti,debtAvailable,"Monthly EMI divided by average monthly income over the last three complete months; full points at 20% or less, declining linearly to zero at 40%."));if(debtAvailable){available+=20;earned=earned.add(debtPoints);}
  List<BudgetService.View> userBudgets=budgets.list(email).stream().filter(b->!b.status().equals("ENDED")&&!b.status().equals("UPCOMING")).toList();boolean budgetAvailable=!userBudgets.isEmpty();BigDecimal budgetTotal=userBudgets.stream().map(BudgetService.View::monthlyLimit).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal budgetSpend=userBudgets.stream().map(BudgetService.View::amountSpent).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal adherence=budgetAvailable&&budgetTotal.signum()>0?budgetSpend.multiply(BigDecimal.valueOf(100)).divide(budgetTotal,2,RoundingMode.HALF_UP):null;BigDecimal budgetPoints=budgetAvailable?budgetTotal.subtract(budgetSpend).signum()>=0?BigDecimal.valueOf(15):BigDecimal.valueOf(15).multiply(BigDecimal.ONE.subtract(budgetSpend.subtract(budgetTotal).divide(budgetTotal.multiply(new BigDecimal("0.20")),8,RoundingMode.HALF_UP))).max(BigDecimal.ZERO):BigDecimal.ZERO;out.add(new Component("budgetAdherence","Budget adherence",15,points(budgetPoints),adherence,budgetAvailable,"Full points when total spending is within active budgets; points decline linearly to zero at 20% overspend."));if(budgetAvailable){available+=15;earned=earned.add(budgetPoints);}
  List<FinancialGoal> userGoals=goals.findAllByUserIdOrderByTargetDateAsc(owner);boolean goalsAvailable=!userGoals.isEmpty();BigDecimal progress=goalsAvailable?userGoals.stream().map(g->g.getCurrentAmount().multiply(BigDecimal.valueOf(100)).divide(g.getTargetAmount(),4,RoundingMode.HALF_UP).min(BigDecimal.valueOf(100))).reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(userGoals.size()),2,RoundingMode.HALF_UP):null;BigDecimal goalPoints=goalsAvailable?progress.multiply(BigDecimal.valueOf(10)).divide(BigDecimal.valueOf(100),8,RoundingMode.HALF_UP):BigDecimal.ZERO;out.add(new Component("goalProgress","Financial goal progress",10,points(goalPoints),progress,goalsAvailable,"Average current-to-target progress across your saved goals, capped at 100%; mapped to 10 points."));if(goalsAvailable){available+=10;earned=earned.add(goalPoints);}
  List<String> limitations=new ArrayList<>();if(available<100)limitations.add("Some score components are unavailable because required transaction, balance, budget, or goal data has not been entered; the displayed score is normalized over available component weights.");if(available<50)limitations.add("Coverage is low, so this score is especially incomplete.");if(avgExpenses.signum()==0)limitations.add("Emergency fund coverage cannot be calculated without expense history in the last three completed months.");if(avgIncome.signum()==0)limitations.add("Debt-to-income cannot be calculated without income history in the last three completed months.");BigDecimal score=available==0?null:earned.multiply(BigDecimal.valueOf(100)).divide(BigDecimal.valueOf(available),0,RoundingMode.HALF_UP);String confidence=available>=80?"HIGH":available>=50?"MEDIUM":available>0?"LOW":"INSUFFICIENT_DATA";return new Assessment(score,available,confidence,List.copyOf(out),List.copyOf(limitations),"This is a transparent budgeting and resilience indicator, not a credit score or financial advice.");}
 private BigDecimal historyAverage(UUID owner,FinancialTransaction.Direction direction){YearMonth m=YearMonth.now();BigDecimal total=BigDecimal.ZERO;for(int i=3;i>=1;i--){YearMonth x=m.minusMonths(i);total=total.add(tx.sumForOwnerAndPeriod(owner,x.atDay(1),x.plusMonths(1).atDay(1),direction));}return total.divide(BigDecimal.valueOf(3),2,RoundingMode.HALF_UP);}
 private BigDecimal ratio(BigDecimal v,BigDecimal cap){return v.divide(cap,8,RoundingMode.HALF_UP).min(BigDecimal.ONE);}
 private BigDecimal points(BigDecimal v){return v.setScale(2,RoundingMode.HALF_UP);}
}
